function animate(env,el,p){
    var marks=["\u030D","\u030E","\u0304","\u0305","\u033F","\u0311","\u0306","\u0310","\u0352","\u0357","\u0351","\u0307","\u0308","\u030A","\u0342","\u0343","\u0344","\u034A","\u034B","\u034C","\u0303","\u0302","\u030C","\u0350","\u0300","\u0301","\u030B","\u030F","\u0312","\u0313"];
    var t=el.text,out="",n=Math.max(0,Math.round(p.intensity*8));
    for(var i=0;i<t.length;i++){ out+=t.charAt(i); if(t.charAt(i)!=" "){ for(var k=0;k<n;k++){ var r=(AM.simplexNoise(i*3.1+k*1.7, p.seed)+1)/2; out+=marks[Math.floor(r*marks.length)%marks.length]; } } }
    el.text=out; return el;
}
